"Ask how many dimes make ${N}.":"اسأل: كم قطعة من فئة العشرة تكوّن {N}؟",
"Count them out if needed.":"عُدّوها إذا لزم الأمر.",
"Two ferries are racing.":"معدّيتان تتسابقان.",
"Which one carries more?":"أيهما تحمل أكثر؟",
"Compare the hundreds first.":"قارن المئات أولًا.",
"If the hundreds are the same, compare the tens.":"إذا تساوت المئات، قارن العشرات.",
"If the tens are the same too, compare the ones.":"إذا تساوت العشرات أيضًا، قارن الآحاد.",
"Look at the hundreds first.":"انظر إلى المئات أولًا.",
"The number with more hundreds is bigger, no matter what the tens and ones say.":"العدد الذي فيه مئات أكثر هو الأكبر، مهما كانت العشرات والآحاد.",
"Pick two prices at the store and ask which costs more and how your child knows.":"اختاروا سعرين في المتجر واسألوا أيهما أغلى وكيف عرف طفلك ذلك.",
