"How much is each jump?":"كم مقدار كل قفزة؟",
"Start number + jumps × jump size.":"عدد البداية + عدد القفزات × مقدار القفزة.",
"Draw a line from {N} to {N} with tick marks every {N} and point to a tick.":"ارسم خطًا من {N} إلى {N} مع علامات كل {N}، وأشر إلى إحدى العلامات.",
"Add or subtract {N} or {N}":"إضافة {N} أو {N} وطرحهما",
