"What changes?":"ما الذي يتغيّر؟",
"Adding {N} adds one ten.":"إضافة {N} تضيف عشرة واحدة.",
"Only the tens digit changes.":"يتغيّر رقم العشرات فقط.",
"Adding {N} adds {W}.":"إضافة {N} تضيف {W}.",
"Only the hundreds digit changes.":"يتغيّر رقم المئات فقط.",
"Which place gets one more, or one less?":"أي منزلة تزيد واحدًا أو تنقص واحدًا؟",
"{N} more means one more ten.":"{N} أكثر تعني عشرة إضافية واحدة.",
"Keep the ones the same.":"أبقِ الآحاد كما هي.",
"Count by tens from a {N}-digit number, like {N}, {N}, {N}.":"عُدّوا بالعشرات ابتداءً من عدد من {N} أرقام، مثل {N}، {N}، {N}.",
"Then try counting by hundreds.":"ثم جرّبوا العدّ بالمئات.",
"Round to the nearest {N}":"التقريب إلى أقرب {N}",
"Which ten is closer?":"أي عشرة أقرب؟",
"Find the two tens the number sits between.":"أوجد العشرتين اللتين يقع العدد بينهما.",
"Look at the ones digit.":"انظر إلى رقم الآحاد.",
"{N} or more goes up; {N} or less goes down.":"{N} أو أكثر نقرّب إلى الأعلى؛ {N} أو أقل نقرّب إلى الأدنى.",
"Which two tens is it between?":"بين أي عشرتين يقع العدد؟",
"The ones digit decides: {N} or more rounds up.":"رقم الآحاد هو الذي يقرّر: {N} أو أكثر نقرّب إلى الأعلى.",
