"Divide with remainders":"القسمة مع باقٍ",
"Equal groups, with some left over.":"مجموعات متساوية، ويبقى بعض الأشياء.",
"Make as many equal groups as you can.":"كوّن أكبر عدد ممكن من المجموعات المتساوية.",
"What is left over is the remainder.":"ما يبقى هو الباقي.",
