"How many groups fit?":"كم مجموعة تتسع؟",
"What is left?":"ماذا بقي؟",
"If what is left could make one more group, make it.":"إذا كان ما بقي يكفي لمجموعة أخرى، فكوّنها.",
"Share a bag of grapes among family members and talk about the leftovers.":"وزّعوا كيسًا من العنب على أفراد العائلة وتحدثوا عمّا بقي.",
