"Factors come in pairs.":"العوامل تأتي أزواجًا.",
"Does it divide with nothing left?":"هل يقسم دون باقٍ؟",
"Find the pair: what times this makes the number?":"أوجد الزوج: ما العدد الذي إذا ضُرب في هذا أعطى العدد؟",
