"Are the pieces the same size?":"هل القطع بالحجم نفسه؟",
"Count the pieces; the size does not change.":"عُدّ القطع؛ الحجم لا يتغيّر.",
"Use measuring cups: {N}/{N} cup plus {N}/{N} cup is {N}/{N} cup.":"استخدموا أكواب القياس: {N}/{N} كوب زائد {N}/{N} كوب يساوي {N}/{N} كوب.",
