"Multiply the top; the bottom stays.":"اضرب البسط؛ ويبقى المقام.",
"How many pieces in each group?":"كم قطعة في كل مجموعة؟",
"Whole × top, same bottom.":"العدد الصحيح × البسط، والمقام نفسه.",
"Each person gets {N}/{N} of a cup of juice.":"يحصل كل شخص على {N}/{N} كوب من العصير.",
"How much for {N} people?":"كم يلزم لـ {N} أشخاص؟",
"Tenths, hundredths and decimals":"الأعشار والأجزاء من مئة والأعداد العشرية",
