"What goes on top?":"ماذا نكتب في البسط؟",
"Divides the larger number by the smaller one in a sharing problem ({N} shared by {N} written as {N}/{N}).":"يقسم العدد الأكبر على الأصغر في مسألة توزيع ({N} موزّعة على {N} مكتوبة {N}/{N}).",
"Divided the other way":"قسم بالعكس",
"Multiply top by top and bottom by bottom.":"اضرب البسط في البسط والمقام في المقام.",
"Multiplies the top of one fraction by the bottom of the other.":"يضرب بسط أحد الكسرين في مقام الآخر.",
"Multiplied across the wrong way":"ضرب متقاطع بالطريقة الخطأ",
"Sharing a piece makes smaller pieces.":"تقسيم قطعة يعطي قطعًا أصغر.",
"Does the bottom number grow?":"هل يكبر المقام؟",
"Divides the denominator when dividing a unit fraction by a whole number, making pieces bigger instead of smaller.":"يقسم المقام عند قسمة كسر وحدة على عدد صحيح، فتصبح القطع أكبر بدلًا من أصغر.",
"Made the pieces bigger":"جعل القطع أكبر",
"Hundredths need two places after the point.":"الأجزاء من مئة تحتاج إلى منزلتين بعد الفاصلة.",
"Writes a number of hundredths below {N} as tenths ({N}/{N} written as {N}).":"يكتب عددًا من الأجزاء من مئة أقل من {N} على أنه أعشار ({N}/{N} مكتوبة {N}).",
"Hundredths as tenths":"الأجزاء من مئة كأنها أعشار",
"Compare tenths first, like comparing hundreds first.":"قارن الأعشار أولًا، كما تقارن المئات أولًا.",
"Thinks the decimal with more digits is bigger ({N} > {N}).":"يظن أن العدد العشري ذا الأرقام الأكثر هو الأكبر ({N} > {N}).",
"Longer decimal is bigger":"العدد العشري الأطول هو الأكبر",
"Times {N} makes every digit worth {N} times more.":"الضرب في {N} يجعل قيمة كل رقم أكبر {N} مرات.",
"Move the digits.":"حرّك الأرقام.",
"Multiplies a decimal by {N}, {N} or {N} by writing zeros at the end instead of moving the digits.":"يضرب عددًا عشريًا في {N} أو {N} أو {N} بكتابة أصفار في النهاية بدلًا من تحريك الأرقام.",
"Added zeros to a decimal":"أضاف أصفارًا إلى عدد عشري",
